namespace BlazorApp.Services;

public class NotificationService
{
    private static readonly string[] Messages =
    [
        "Your order has been shipped",
        "New comment on your post",
        "System maintenance scheduled for tonight",
        "Welcome to the platform!",
        "Your password was changed successfully",
        "New follower: Jane Doe",
        "Payment received — thank you!",
        "Your report is ready to download",
        "Security alert: new login from Chrome on Windows",
        "Weekly digest: 12 unread messages",
    ];

    private int _counter;

    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        var now = DateTime.Now;
        var items = new List<NotificationItem>
        {
            new(++_counter, Messages[0], now.AddMinutes(-30)),
            new(++_counter, Messages[1], now.AddMinutes(-15)),
            new(++_counter, Messages[2], now.AddMinutes(-5)),
        };
        return Task.FromResult(items);
    }

    public Task<List<NotificationItem>> CheckForNewNotificationsAsync()
    {
        // Simulate: ~50 % chance a new notification arrives each poll
        if (Random.Shared.NextDouble() < 0.5)
        {
            return Task.FromResult<List<NotificationItem>>([]);
        }

        var msg = Messages[Random.Shared.Next(Messages.Length)];
        var item = new NotificationItem(++_counter, msg, DateTime.Now);
        return Task.FromResult(new List<NotificationItem> { item });
    }
}

public record NotificationItem(int Id, string Message, DateTime Timestamp);

